-- Generated by scripts/letters.ts from i18n/deDE/letters/: edit those, not this file.
-- letterTexts[id] = { greeting, body = { paragraph, ... }, signoff (its lines), ps = { paragraph, ... } }
local _, ns = ...
ns.letterTexts = {
  [1] = { greeting = "$N,", body = { "ich kannte Edwin van Cleefs Namen lange, bevor ich von seinen Verbrechen wusste. In Sturmwind stehen Mauern, die er mit eigenen Händen errichtet hat. Ich bin froh, dass es vorbei ist, und es hat mir keine Freude gemacht, Euch darum zu bitten.", "Furlbrow will seine Familie nach Hause bringen. Ich musste ihm sagen: noch nicht. Er wollte einen Tag, den er sich anstreichen kann, und ich konnte ihm keinen geben. Wir brauchen noch immer Männer auf den Straßen.", "Die Nachtwache verlief ohne Alarm. Ich traue dem noch nicht, und ich habe den Männern gesagt, dass sie ihm auch nicht trauen sollen.", "Ihr habt meinen Dank und den der Miliz. Ich wollte, dass Ihr ihn von mir hört." }, signoff = "Gryan Stoutmantle\nDie Volksmiliz" },
  [2] = { greeting = "$gLieber:Liebe; $N,", body = { "das Denkmal ist fertig, wie man mir sagt, und Großsteinmetz Marblesten ist zufrieden mit dem Alteracgranit, den Ihr ihm gebracht habt. Ich habe unseren König gefragt, was uns der Krieg kosten würde. Er hat mir in Granit geantwortet. Den Steinmetz habe ich nur gefragt, ob Sullys Name tief genug gemeißelt ist, um lesbar zu bleiben, wenn der Stein zu verwittern beginnt. Vielleicht ist das eine törichte Frage. Mir war sie wichtig.", "Ich habe seinen Brief schon mehrmals weggelegt. Dann fragt einer der Jungen, was sein Vater geschrieben hat, und ich hole ihn wieder hervor. Der kleine Edgar weiß inzwischen, wo ich innehalte, und wartet dort auf mich, bevor ich die Seite umblättere.", "Es stehen Dinge darin, die Sully mir nie gesagt hat, als er zu Hause war. Seltsam, sie jetzt zu hören, in seiner eigenen Handschrift. Ich hätte ihm gern geantwortet.", "Danke, dass Ihr ihn uns zurückgebracht habt. Ich hätte es nicht ertragen, auch das noch zu verlieren." }, signoff = "In Dankbarkeit\nSara Balloo" },
  [3] = { greeting = "$C,", body = { "Ramsteins Kopf hängt an der Wand. Die Hunde fressen lebendige Fäulnis, ohne zu murren. Unter diesem Kopf fressen sie nicht. Ich habe ihre Näpfe umgestellt.", "Ich habe Ramstein monatelang gejagt, bevor er sich nach Stratholme flüchtete. Ihn hier zu haben, hat am Zustand des Hofs wenig geändert. Ich hatte es nicht erwartet. Ich wollte das Ding tot sehen, und Ihr habt dafür gesorgt.", "Ihr kamt mit Stroh im Kopf auf mein Gehöft. Jetzt gehört Ihr zu meinen Champions. Ich halte das schriftlich fest, weil Ihr es sonst nicht glauben würdet. Versucht, nicht anschwellen zu lassen, was bei Euch als Kopf durchgeht.", "So. Nun habt Ihr es." }, signoff = "Nathanos" },
  [4] = { greeting = "$N,", body = { "meine Mutter war froh zu hören, dass du vor Cairne gestanden hast, mein Kind, und ihr erster Gedanke war, ob du vor dem Aufstieg etwas gegessen hattest. Ich konnte es ihr nicht sagen, und sie findet, ein Häuptling sollte so etwas wissen.", "Sie geht noch immer selbst zum Brunnen, um ihr Wasser zu holen. Als ich anbot, den Krug zu tragen, fragte sie, ob ein Häuptling nichts Besseres zu tun habe. Und als ich sagte, dass du ihn einmal für sie getragen hast, meinte sie, in der Zeit, die ich dafür brauchte, hätte ich das Wasser schon holen können.", "Baine hat mir Nachricht von dir geschickt, und ich habe sie den anderen am Feuer vorgelesen. Die Kleinen ließen sie mich zweimal lesen, und seitdem reden sie jeden Abend von den Riten.", "Meine Mutter sagt, dieser Brief habe zu viele Ecken, wie meine Schnitzereien. Ich habe ihr gesagt, du würdest ihn trotzdem lesen." }, signoff = "Wandle mit der Erdenmutter,\nHäuptling Hawkwind" },
  [5] = { greeting = "$gKleiner:Kleine;,", body = { "die Linse sitzt, das Teleskop funktioniert, und die Stiefel stehen wieder in den Regalen. Die Kunden fragen nicht mehr, wo sie geblieben sind. Die schönste Ruhe, die ich je bezahlt habe.", "Hör zu. Dizzywig hat deinen Lohn unter Fracht verbucht. Ich hab ihn das ändern lassen. Fracht marschiert nicht in ein Piratenlager und mit den richtigen Kisten wieder raus. Nach meinen Büchern schulde ich dir damit die Differenz. Also muss Dizzywig die Bücher in Ordnung bringen. Nicht die Differenz, $gKleiner:Kleine;. Die Bücher.", "In Ratchet verspricht jeder was. Neunundneunzig von hundert kommen mit einer Geschichte zurück, warum es nicht ging. Du bist mit meinen Stiefeln zurückgekommen. In meiner Branche ist das seltener als Gold, und ich muss es wissen." }, signoff = "Gazlowe", ps = { "P.S. Die Piraten sind wieder am Strand. Ich hab ihnen eine Rechnung geschickt." } },
  [6] = { greeting = "$gMein lieber:Meine liebe; $N!", body = { "Bangalash! Das ganze Lager schreit beim Abendessen noch immer von ihm! Sire Erlgadin schwört, sein Panther sei das zähere Wild gewesen, und Ajeck will davon kein Wort hören. Ich musste den Kessel zweimal vor ihren Vorführungen in Sicherheit bringen.", "Erlgadin, Ajeck und ich haben alle eine Menge zu sagen über einen gewissen Tiger, den Ihr erlegt habt! Ich hatte diesen weißen Teufel sehr lange im Visier, und ich habe mir ein Wort oder zwei dazu redlich verdient!", "Barnil hat meinen Bericht über die Jagd gelesen und gefragt, wo Ihr darin vorkommt. Berechtigte Frage! Ich fürchte, ich habe mich von meinen eigenen Jagdversuchen so hinreißen lassen, dass ich Euch ganz vergessen habe. Na schön, ich habe Euch wieder dorthin gesetzt, wo Ihr hingehört.", "Verflixt gut gemacht! Auf Euch, sage ich! Auf Euch!" }, signoff = "Hemet Nesingwary" },
  [7] = { greeting = "Grüße aus der Höhle, $N!", body = { "Ich bin immer noch genau da, wo du mich gefunden hast. Mir geht es wieder richtig gut, versprochen. Na ja, fast. Zwischen mir und dem Rest von Shadowglen sitzen noch eine Menge Waldweberspinnen, und ein vernünftiger Elf wartet, bis sie beschäftigt aussehen.", "Dirania lässt mir ausrichten, dass ich wieder nach Hause laufen kann. Sie erinnert mich auch jedes Mal daran, dass sie mich immer vor diesen Spinnen gewarnt hat. Na ja, hat sie.", "Früher habe ich sie jeden Tag zur selben Zeit besucht. Jetzt weiß sie zu jeder Stunde genau, wo ich bin, und ich glaube, das ist ihr lieber.", "Ich gerate ständig in Schwierigkeiten, und irgendwer holt mich immer wieder raus. Meistens ist es Dirania. Diesmal warst du es, in nur fünf Minuten. Danke." }, signoff = "Dein Freund\nIverron" },
  [8] = { greeting = "$N,", body = { "die Frucht, die Ihr gefunden habt, ist das Interessanteste in meinem Lager. Ich halte sie eingewickelt, weit weg vom Boden, bis ich verstehe, was zwischen den beiden vorgegangen ist. Lag der Fehler in der Frucht oder in der Erde von Teldrassil? Mir wäre die Frucht lieber.", "Die Bäumlingssamen liegen in der besonderen Erde, vermischt mit der seltenen, die Ihr aus Dolanaar gebracht habt, und ich sehe öfter nach ihnen, als es nützt. Man sagt mir, ein beobachteter Samen keime nie. Ich habe das weder bestätigt noch widerlegt gefunden.", "Was ich weiß: Die Pflanze, die die Frucht trug, ist hier fremd. Vielleicht kam ihr Samen von sehr weit her. Was ich nicht weiß: so gut wie alles andere. Eine wunderbare Lage.", "Ihr habt ein gutes Auge, $N. Danke, dass Ihr es mir geliehen habt." }, signoff = "Hochachtungsvoll\nDenalan" },
  [9] = { greeting = "$N!", body = { "Ich hab's getan!! Ich habe jeden Tropfen getrunken und bin direkt am Haus vorbeigegangen, und niemand hat etwas gesehen. Überhaupt nichts! Ich konnte meine eigenen Schritte hören und war sicher, der ganze Weinberg hört sie auch.", "Tommy Joe war am Fluss, genau da, wo er immer ist. Natürlich konnte er mich auch nicht sehen, also musste ich seinen Namen sagen, und er ist so hoch gesprungen, dass ich dachte, er fällt hinein. Dann hat er gelacht, und dann ich, und wir haben geredet, bis ich meine eigenen Hände wieder sehen konnte. Ich bin den ganzen Weg nach Hause gerannt.", "Ich weiß, es war schlimm, meine Familie zu täuschen. Ich würde es sofort wieder tun!", "Ich kann nicht einmal Herrn Pestle oder Oma Stonefield danken, weil ich die beiden ja gar nicht kennen darf!", "Ihr habt meinen Brief zu Tommy Joe gebracht. Dieser hier ist für Euch." }, signoff = "In Liebe (aber nicht so!),\nM." },
  [10] = { greeting = "$gLieber:Liebe; $N,", body = { "die Halskette ist wieder, wo sie hingehört. Ich schlafe mit ihr. Sollen die Kobolde es nur versuchen.", "Dieser Billy Maclure erzählt jedem, der stehen bleibt, meine Pastete sei die beste, die er je gegessen hat. Natürlich war sie das. Darum geht es nicht. Es geht darum, dass er meine Halskette genommen und für seine Mühe auch noch Pastete bekommen hat, und jetzt kennt der halbe Wald meine Pastete besser als meinen Namen.", "Ich habe dir die Handschuhe meines Mannes gegeben, weil sie am Haken neben der Tür niemandem etwas nützten. Er hat immer gesagt, sie bringen Glück, und dann ist er ohne sie auf seinen letzten Feldzug gezogen. Ich habe diesen Haken lange angesehen. Besser, sie gehen mit jemandem zur Tür hinaus.", "Danke, Kindchen. Du hast einer alten Witwe das Herz gewärmt, auch wenn ich das vor jedem Maclure abstreite, der fragt." }, signoff = "Tantchen Bernice", ps = { "P.S. Ich habe nichts in Billys Pastete getan. Ich hab drüber nachgedacht." } },
  [11] = { greeting = "Seid gegrüßt, $N!", body = { "Mein Bruder sagt, das Schimmerstarkbier bringe ihm Glanz in die Augen, und er könne im Dunkeln sehen. Gebirgsjäger Kadrell hat aus Thelsamar geschrieben, es mache die Glieder leicht, und er fühle sich, als könne er fliegen. Von solchen Worten könnte ein Brauer leben, und beinahe tue ich das. Danke, dass Ihr es ihnen gebracht habt, $gJunge:Mädel;.", "Der Haken ist nur: Es ist nicht perfekt. Ein Starkbier, bei dem ein Zwerg glaubt, er könne fliegen, ist ein gutes Starkbier. Ein perfektes Starkbier lässt ihm die Stiefel auf dem Boden und macht ihn froh darüber. Das Schimmerkraut ist die richtige Note. Es ist das Malz darunter, das nicht stimmt, zu süß oder nicht dunkel genug, und ich habe drei kleine Sude angesetzt, um es herauszufinden.", "Das Brauen liegt mir im Blut, und Blut ist geduldig. Ich komme schon noch hin." }, signoff = "Rejold Gerstenbräu" },
  [12] = { greeting = "$N,", body = { "Holz: zu wenig. Peons: schlafen. Zwei unter demselben Baum, einer auf dem Holzstapel und einer im Stehen. Ich wusste nicht, dass die das können.", "An dich erinnern sie sich aber. Es hat sich rumgesprochen, dass du mit meinem Totschläger durchs Tal gezogen bist. Wenn jetzt einer Schritte hört, steht er auf und schwingt die Axt, bevor er die Augen offen hat. Hält nicht lange. Besser als nichts.", "Sie fragen, ob du wiederkommst. Ich sag ja. Ich sag nicht, wann.", "Gute Arbeit. Danke für die Hilfe." }, signoff = "Thazz'ril\nGroßknecht" },
  [13] = { greeting = "$N,", body = { "in der Nacht, als Ihr mir den Kopf brachtet, habe ich nicht geschlafen. Ich saß am Wasser und lauschte. Keine Trommeln kamen von den Inseln herüber. Hinter mir schlief das Dorf, das ganze Dorf, so wie früher. Das wollte ich hören.", "Vom Ufer aus sieht man die Echoinseln. Ich weiß noch, welcher Strand meiner war. Sie gehören nicht uns. Ich sehe trotzdem hin.", "Manche von denen, gegen die Ihr gekämpft habt, gehörten zu den Darkspear, vor der Verhexung. Trauert nicht um sie. Das ist unsere Sache, und wir haben es getan." }, signoff = "Gadrin" },
  [14] = { greeting = "$gJunger:Junge; $N,", body = { "die Tiere trinken wieder am Wasserbrunnen von Winterhoof, so begierig wie an dem Tag, an dem er gereinigt wurde. Ich habe zugesehen, wie sich die Ebenenschreiter zu ihm hinabbeugen und danach die Wölfe herunterkommen, und jedes Mal dachte ich, dass sie von einem Wasser trinken, das ihre eigene Art mit gereinigt hat. Sie wissen es nicht, aber das Land weiß es, und ich weiß es auch.", "Jedes Totem verlangte etwas von den Tieren Mulgores, bis hin zu den Zähnen der Alphatiere, und mein Geist ist ihretwegen noch immer schwer, und stolz. Sie haben nicht freiwillig gegeben, und Ihr habt ihre Gabe zu den Brunnen getragen.", "Wenn der Wind von Norden herabweht, höre ich die Geister von Euch sprechen." }, signoff = "Mögen die Geister Euch leiten,\nMull Thunderhorn" },
  [15] = { greeting = "$N,", body = { "hiermit bestätige ich den Eingang des Berichts von Todeswache Linnea, von Eurer Hand und ohne Verzug überbracht. In Brill ist Pünktlichkeit selten genug, um der Erwähnung wert zu sein.", "Der Bericht besagt, was sie Euch gesagt hat. Das Bollwerk hält den größeren Teil der Geißel auf, und einige schlüpfen hindurch. Ich habe ihn zu den anderen gelegt, die dasselbe besagen.", "Die Gräber bei Garrens Schlupfwinkel sind nicht sicher, doch die Toten darin bleiben tot, und darum ging es. Den Toten blieb erspart, was man uns angetan hat. Ich stelle fest, dass ich ein persönliches Interesse daran habe, dass es so bleibt, und Eure Arbeit unter den Moderfellen hat dem gedient. Die Apotheker haben das Sekret. Sie haben mir nichts gesagt, was nach meiner Erfahrung bedeutet, dass sie zufrieden sind.", "Der Lichkönig und seine Diener greifen uns unaufhörlich an. Er wird nicht noch einmal von uns Besitz ergreifen." }, signoff = "Mit meinem amtlichen Dank\nMagistrat Sevren" },
  [16] = { greeting = "$N,", body = { "spürt Ihr es noch, das Summen bei den Menhiren? Ja? Gut. Dann hat es gewirkt, und Ihr werdet es an vielen Orten wieder spüren.", "Leylinien lebten früher in alten Büchern. Jetzt kommen sie durch das Gras herauf, uns entgegen. Ob Gabe oder Warnung, es ist Wissen, und ich will alles davon haben, bevor jemand anderes entscheidet, was ich wissen darf.", "Rorian hat Euch Euer Relikt überreicht und gesagt, heimische Winde würden Euch begleiten, wo immer Eure Reise Euch hinführt. Rorian glaubt das, und es ist ein freundlicher Glaube. Mir ist lieber, was ich messen kann.", "Es sind schlimme Zeiten für die Shen'dorei, und ich weiß, was ich zuerst will: Wissen, dann Macht." }, signoff = "Erschließt das Unbekannte,\nFalorne Fallwind" },
  [17] = { greeting = "$N,", body = { "wie einen Muskel müsst Ihr Eure Himmelssicht trainieren, und ein Muskel, den man ruhen lässt, wird schlaff. Nutzt sie unterwegs, im Gasthaus, im Regen. An den meisten Tagen werdet Ihr nichts sehen, was des Sehens wert ist. Nutzt sie trotzdem.", "Ich halte meine jeden Abend ein wenig offen, hier im Dorf, bevor ich schlafe. An manchen Abenden fange ich ein, zwei Worte auf, leise wie eine Stimme durch eine Wand. An manchen Abenden nichts. Ich habe gelernt, den stillen Abenden nicht zu grollen. Auch sie gehören zur Übung.", "Ich schreibe auf, was ich auffange, auch wenn es keinen Sinn ergibt. Gerade dann. Die Geister wiederholen sich nicht, nur weil es uns gelegen käme.", "Wir werden jeden brauchen, der zuhören kann." }, signoff = "Geduld,\nVentaari Brightwish" },
  [18] = { greeting = "$N,", body = { "ich habe Belathaan zum Schrein von Akir geschickt, weil die Logik es gebot. Reden kostet weniger als Blut, und Frieden weniger als Krieg. Jeder Schritt dieser Überlegung war schlüssig. Der Kult hat mit einer Kiste geantwortet. Ich bin meine Argumente seither viele Male durchgegangen, auf der Suche nach dem Fehler, und ich finde ihn nur in meiner Einschätzung derer, zu denen ich ihn geschickt habe.", "Die Windformer hatten recht. Das niederzuschreiben ist schlimmer, als es auszusprechen.", "Die Gebetsamulette, die Ihr mir gebracht habt, liegen unter Verschluss. Ich sehe sie seltener an als früher. Ich habe nicht vergessen, wer sie mir gebracht hat.", "Der Kult hat unsere Klugheit als Schwäche missverstanden. Auch das war eine Einschätzung, und seine ist die schlechtere." }, signoff = "Elaadrin Evengale\nOberster Magister des Hohen Ordens" },
  [19] = { greeting = "$N,", body = { "ich schulde Euch eine bessere Antwort als die, die ich Euch gab, als Ihr mir die Amulette brachtet. „Ein schwieriger Tag“ war keine.", "Windformer vergelten Blut immer mit Blut. Ich habe es mein Leben lang gesagt, und ich meinte es, als ich Euch nach Norden schickte. Ich meine es noch immer. Die Novizen, die wir im Hochland fanden, waren die unseren, und jemand wird für jeden von ihnen büßen.", "Aber ich hatte Euch auch hinter Belathaan hergeschickt, um ihm Angst einzujagen, und er kam von dieser Straße nie zurück. Ich sagte Euch, es sei nicht Eure Schuld. Das war wahr. Ich sagte nicht, wessen Schuld es war, weil ich es noch nicht entschieden hatte. Elaadrins, weil er ihn schickte. Die des Kults, weil er ihn tötete. Meine, weil ich wollte, dass er Angst hat. Seine Mutter war eine von uns.", "Wir vergeben und vergessen nicht. Auch ihn werde ich nicht vergessen." }, signoff = "Ayessa Dawnsinger\nHohe Himmelseherin der Windformer" },
  [20] = { greeting = "$N,", body = { "der Damm steht noch! Ich gehe jeden Morgen und jeden Abend hinunter zu seinem Fuß, um nachzusehen, und er steht noch, und jedes Mal danke ich den Sternen. Ach du meine Güte, ich hoffe, Ihr erfahrt nie, was dieses Pulver nass angerichtet hätte. Ich habe es zweimal auf dem Papier durchgerechnet, und dann habe ich aufgehört, es durchzurechnen!!", "Die Sicherheitstruppe ist noch immer an der Front der Allianz, und mein bester Inspektor mit ihr. Also sind da nur ich, die Gebirgsjäger, die man mir leiht, und das Wasser. Ich klopfe jetzt an jedes Fass, an dem ich vorbeikomme. An jedes einzelne.", "Ihr kamt, als sonst niemand kam, und Ihr habt in diesem Fässchen gerührt, als wäre es Suppe. Ich weiß nicht, ob das Mut war oder Ahnungslosigkeit, und ich bin für beides dankbar!", "Der Damm ist sicher, zumindest vorerst, und alle, die unter ihm leben, auch." }, signoff = "In einiger Eile\nHinderweir VII.\nChefingenieur, Stonewroughtdamm" },
  [21] = { greeting = "$N,", body = { "ausnahmsweise ein Brief von mir, den Ihr nirgendwohin tragen müsst.", "Ich habe die drei Antworten, die Ihr mir gebracht habt, öfter gelesen, als ein Magistrat irgendetwas lesen sollte. Sturmwind wird Verstärkung schicken, sobald der König den Befehl gibt. Westfall hat keine Männer übrig und muss seine eigenen Toten begraben. Dunkelhain kann seine Nachtwache nicht über den Rand des eigenen Waldes hinausschicken. Jede Antwort ist vernünftig. Zusammen ergeben sie überhaupt keinen Sinn.", "Seenhain hält stand, fürs Erste. Irgendwo in alldem steckt Verrat, und ich will herausfinden, wessen. Pah. Ich sollte nicht laut grübeln, nicht einmal auf dem Papier.", "Ihr seid einen weiten Weg gegangen für eine Gemeinde, die Euch nichts schuldete, und jedes Mal seid Ihr mit der Wahrheit zurückgekehrt, selbst wenn die Wahrheit Nein lautete. Ich danke Euch." }, signoff = "Magistrat Solomon\nSeenhain" },
  [22] = { greeting = "$N,", body = { "Hollee erzählt mir, dass Ihr mich aus der Grabung geführt habt, und dass ich nicht, wie ich damals glaubte, einfach einen Spaziergang gemacht habe. Sie sagt, da waren Golems. Ich erinnere mich an eine sehr interessante Sedimentschicht.", "Sie erzählt mir auch, dass mein Fossil in Darnassus war und dann im Hafen von Menethil, was mehr Reisen sind, als ich in Jahren gemacht habe, und dass ein gewisser Flagongut es jetzt hat, zusammen mit einem Stein von ihm selbst. Großartig! Ich hoffe, er schreibt. Ich hoffe, er schreibt mir, meine ich, und nicht Hollee, obwohl Hollee wirklich alles zu bekommen scheint.", "Ich suche meinen Steinpinsel. Ich erwähne es nur, weil ich ihn die ganze Zeit gesucht habe, während ich das hier schrieb, und es mir unhöflich vorkam, es nicht zu sagen." }, signoff = "Mit Dank und, glaube ich, Entschuldigungen\nAusgrabungsleiter Remtravel" },
  [23] = { greeting = "$N,", body = { "das NG-5 ist in einwandfreiem Zustand angekommen, will sagen, es ist dir unterwegs nicht um die Ohren geflogen, und das zähle ich als Erfolg für alle Beteiligten!", "Lomac ist der beste Chemiker, der mich je angebrüllt hat. Wenn er dir Grüße aufgetragen hat, dann meinte er sie. Wenn er sonst etwas gesagt hat, meinte er das auch, nur weniger.", "Alles ist an Ort und Stelle. Ich verrate dir den Plan nicht, zum einen, weil ein verratener Plan ein verdorbener Plan ist, zum anderen, weil er sich jedes Mal ändert, wenn ich ihn ansehe. Es kommen Wagen darin vor. Es kommt Dynamit darin vor, das gar nicht so gefährlich ist, wie alle meinen. Es kommen Magie, Mixturen und Mechanismen darin vor, die alle zusammenarbeiten, und genau darum geht es bei der Vereinigung und, ehrlich gesagt, bei mir.", "Die Nachtelfen sehen mich immer noch an, als könnte ich jeden Moment hochgehen. Das ist nur fair. Ihnen zu zeigen, dass ein Gnom helfen kann, ihre Wälder zu retten, ist mein Ziel, nein, meine PFLICHT!" }, signoff = "Gaxim Rustfizzle\nErleuchtete Vereinigung der Arkanologie, Alchimie und Ingenieurwissenschaften" },
  [24] = { greeting = "$N,", body = { "die Zeit der Trauer ist gekommen, wie ich es sagte, und sie hält sich an keine Stunde, die ich wählen würde. Ich habe Teronis' Familie geschrieben. Es war der kürzeste Brief, den ich je geschrieben habe, und er hat mich die ganze Nacht gekostet.", "Ihr habt ihn gefunden, und Ihr habt gefunden, wonach er suchte, als er starb. Es war mehr, als ich zu hoffen wagte, und es ist nicht genug.", "Die Furbolgs waren nicht immer unsere Feinde. Als ich jung war, habe ich nicht ein einziges Mal den Bogen auf einen von ihnen gerichtet. Jetzt habe ich Euch die Straße hinab zu ihren Lagern geschickt und es Verteidigung genannt, und das war es. Ich möchte nur, dass irgendwo geschrieben steht, dass ich mich an die ruhigere Zeit erinnere." }, signoff = "Möge Elune über Euch wachen,\nRaene Wolfrunner" },
  [25] = { greeting = "$N,", body = { "ich habe es der Hohepriesterin gesagt. Was zwischen uns gesprochen wurde, behalte ich für mich. Ich sage nur, dass ich den langen Weg zurück zur Unterkunft genommen habe.", "Velindes Truhe steht noch in der Unterkunft. Ich bringe es nicht über mich, sie leeren zu lassen. Die Schildwachen glaubten, sie habe ihre eigenen Gründe zu gehen und werde zurückkehren, wann sie wolle. Ich glaubte es auch, und ich sagte es Euch. Ich hätte mich lieber in fast allem anderen geirrt.", "Es beunruhigt mich, dass die Sense von Elune den Händen ihrer Dienerinnen entglitten ist.", "Ihr seid ihr um die halbe Welt gefolgt, auf das Wort eines Buches hin, das sich selbst schreibt. Wenige hätten das getan. Ich schulde Euch Dank, und zwar nicht wenig." }, signoff = "Thyn'tel Bladeweaver" },
  [26] = { greeting = "$C,", body = { "verzeiht meinen Zorn, als Ihr mich aufsuchtet. Ich war wütend wie ein tollwütiger Kodobulle, und Ihr hattet nichts getan, um es zu verdienen. Die Schuld lag bei mir. Ich schickte Reisende hinab unter die Stadt, ohne daran zu denken, wer ihnen noch folgen könnte, und zwei Freunde haben für meine Nachlässigkeit bezahlt. Thralls Weltverbesserer, wer immer sie waren. Ich gäbe viel für ihre Namen.", "Ich bringe dort unten in Ordnung, was ich kann. Unsere Freunde im Brachland und im Wald haben ihre eigene Arbeit begonnen.", "Ihr kamt im richtigen Augenblick zu mir, mit dem richtigen Abzeichen. Das vergesse ich nicht. In einer Stadt, in der so wenige sind, was sie scheinen, ist es ein Trost, jemanden zu kennen, der es ist." }, signoff = "Ein Freund in der Kluft" },
  [27] = { greeting = "$N,", body = { "ich habe den Pyrewood-Fesseln, die Ihr mir gebracht habt, entnommen, was ich konnte. Es war nicht genug. Das vermutete ich, und ich glaube, ich habe es gesagt. Eine begrenzte Probe ist eine begrenzte Probe.", "Trotzdem verstehe ich das Gegenmittel jetzt, oder das meiste davon, und je besser ich es verstehe, desto weniger halte ich von dem Mann, der den Zauber gewirkt hat. Die Kirin Tor haben ihn in ihre Hallen gelassen. Ich habe aufgehört zu fragen, wie.", "In Pyrewood sind sie tagsüber noch immer Männer und Frauen, und noch immer etwas anderes, wenn die Sonne untergeht. Arugal hat das einem ganzen Dorf angetan, mit einem Zauber, den zu unterzeichnen sich jeder Lehrling schämen würde. Das finde ich am schwersten zu verzeihen. Nicht den Fluch. Die Machart.", "Es wird länger dauern, als ich dachte. Alles, was mit Arugal zu tun hat, dauert länger, als ich denke. Es ist vielleicht seine einzige Begabung.", "Meine Hochachtung, $N." }, signoff = "Dalar Dawnweaver\nDas Grabmal" },
  [28] = { greeting = "$N,", body = { "bevor Ihr zur Insel Fenris aufbracht, schrieb ich zwei Berichte für Undercity. Der eine besagte, dass Thule Rabenklaue tot sei. Der andere, dass ich Euch hinter ihm hergeschickt habe und Ihr nicht zurückgekehrt seid. Ein Befehlshaber sollte auf beides vorbereitet sein. Den zweiten habe ich an dem Tag verbrannt, an dem Ihr mit seinem Kopf zurückkamt.", "Renferrel sagt mir, die Energien, die bei Thules Fall frei wurden, seien bis zum Grabmal zu spüren gewesen. Er hat recht. Ich habe es selbst gespürt, und ich wusste, was Ihr getan hattet, bevor es mir jemand sagte.", "Die Geißel ist mit dem Silberwald nicht fertig. Die Moderfelle halten die Insel noch immer, und für einen toten Magier werden sie sie nicht räumen. Aber sie haben Boden verloren, und sie haben ihn an die Unseren verloren.", "Euer Wert für uns wächst." }, signoff = "Hochexekutor Hadrec\nDas Grabmal" },
  [29] = { greeting = "$N,", body = { "ich kann nicht gut schreiben. Sie war die mit den Worten.", "Sie hat drei Stacheleber allein aufgehalten. Als mehr kamen, habe ich ein paar weggelockt und mir gesagt, das sei der mutige Teil. Das sage ich mir jetzt nicht mehr.", "Der Druide, der mich auf der Straße fand, sagte, ich solle mich ausruhen. Ich habe mich ausgeruht. Dann bin ich zu dem Lager zurück, wo wir getrennt wurden, und habe jeden Stacheleber getötet, den ich dort fand. Das hat auch nicht geholfen.", "Ihr habt sie gefunden, als ich es nicht konnte. Ich weiß nicht, was Ihr dort gesehen habt, und ich frage nicht.", "Danke, $C." }, signoff = "Mankrik" },
  [30] = { greeting = "$N,", body = { "ich habe die Nacht durchgeschlafen. Die ganze, von der Dunkelheit bis zum ersten Licht auf der Anhöhe, und ich bin mit offenen Händen aufgewacht. Ich hatte vergessen, dass Schlaf so schlicht sein kann.", "Als der Älteste den Traum verließ, blieb ich, weil jemand ihre Gesichter sehen musste. Ich sah sie. Dann konnte ich nicht mehr aufhören, sie zu sehen. Vier Gesichter, die sich mir jede Nacht zuwandten, als kennten sie mich. Ich wachte mit geballten Fäusten und schmerzenden Zähnen auf. Sie kommen nicht mehr.", "Sie waren einmal Druiden. Ihr Orden wollte das Brachland heilen. Ich denke öfter daran, als mir lieb ist. Es wäre leichter, sie zu hassen, wenn sie schon immer gewesen wären, was sie wurden.", "Das Land träumt noch immer, und schlecht. Das war nie das Werk einer einzigen Nacht. Aber meine Träume gehören wieder mir, und Ihr habt sie zurückgeholt." }, signoff = "Nara Wildmane" },
  [31] = { greeting = "$N,", body = { "die Bunker haben gehalten. Krom'zar kam den ganzen Weg aus Desolace, um Rache zu üben, und er fand Euch.", "Barak, Verog, Hezrul und dann Krom'zar. Ich habe fast mein ganzes Leben gegen Zentauren gekämpft, und nie habe ich vier ihrer Anführer durch eine einzige Hand fallen sehen. Ein Zentaur mit genug Verstand zum Führen ist selten, und das sind die gefährlichen. Ihr habt Euch die gefährlichen vorgenommen.", "Die Kolkar werden wiederkommen. Das haben sie immer getan. Wenn sie kommen, werden sie einander von Euch erzählen, und ich hoffe, sie erzählen es schlecht.", "Schreitet erhobenen Hauptes, $N." }, signoff = "Regthar Deathgate" },
  [32] = { greeting = "$R,", body = { "Quetschzahn schreibt. <schnaubt> Hände nicht gemacht für Federn. Lest trotzdem.", "Quetschzahn sah Euch laufen, aus dem Käfig. Ihr seid mit den Zhevras gelaufen. Der Wind war eifersüchtig, wie Quetschzahn gesagt hat. <schnaubt> Agammagans Geist antwortet Quetschzahn noch immer, Gitter hin oder her. Kein Käfig hält das auf. Merkt Euch das.", "Borstennacken jetzt schwächer, dank Euch und dank Quetschzahn. Und immer noch kommen die Grimmhauer nicht. Quetschzahn hat die Tage gezählt. Dann hat Quetschzahn aufgehört zu zählen. <schnaubt>", "Die Berührung der Splitter. Lange her, dass Quetschzahn einen hielt. Ihr wisst nicht, wie es ist, wenn man seiner Macht beraubt wird. Quetschzahn hofft, Ihr erfahrt es nie.", "Quetschzahn ist kein Narr. Quetschzahn ist dankbar. Beides. <schnaubt>" }, signoff = "Quetschzahn\nCamp Taurajo" },
  [33] = { greeting = "$N,", body = { "die Goblins roden die Scherwindklippe noch immer. Bei Westwind rieche ich ihren Rauch bis hierher an die Grenze. Zwei kaputte Maschinen werden sie nichts lehren, und das habe ich auch nie geglaubt.", "Aber das meiste Klagen hat aufgehört. Nicht die Trauer, das Klagen. Die Geister sind verletzt, noch immer, und sie haben jedes Recht dazu. Blind vor Schmerz sind sie nicht mehr.", "Vielleicht müssen die Ältesten noch kommen und beruhigen, was übrig ist. Das habe ich Euch schon gesagt. Ich sage es noch einmal, damit Ihr nie einen Sieg mit einem Wald verwechselt.", "Die Geister haben mir die Zeichen auf diesen Maschinen gegeben. Ihr habt mit den Maschinen in der einzigen Sprache gesprochen, die Goblins verstehen. Ich halte das für eine gerechte Arbeitsteilung." }, signoff = "In Zorn und in Hoffnung\nSeereth Stonebreak" },
  [34] = { greeting = "$gBeneidenswerter:Beneidenswerte; $N!", body = { "Dreißig! Dreißig kostbare Schädel, und jeder einzelne wunderschön! Ich zähle sie bei jeder Wachablösung, falls einer irgendwohin gerollt ist. Keiner hat sich davongemacht. Sie benehmen sich tadellos.", "Ich bewahre sie außer Sicht auf, wo Darthalia sie nicht sehen kann. Sie findet, eine Todeswache im Dienst sollte Wache halten. Das tue ich. Ich bewache sie mit größter Sorgfalt.", "An diesem Posten passiert nie etwas. Während Ihr draußen in Hillsbrad die Zeit Eures Lebens hattet, war ich so neidisch, dass ich fast in Stücke zerfallen wäre, was in meinem Alter ein echtes Risiko ist.", "Ich hoffe doch, Ihr haltet am Tor, wenn Ihr vorbeikommt, und sei es nur, damit ich Euch noch einmal danken kann." }, signoff = "Eure ergebene Todeswache\nSamsa\nTarrens Mühle" },
  [35] = { greeting = "$N,", body = { "der Hafen ist offen. Schiffe rein, Schiffe raus, und keine Mannschaft beobachtet die Hügel, während sie festmacht. Das ist Euer Werk.", "Ich sag Euch, was ich Valstag gesagt habe. Eine Belagerungsmaschine ist ein geduldiges Ding. Sie hockt in den Hügeln und wartet, bis man es sich bequem macht. Nek'roshs Maschinen warteten auf uns, und Ihr habt an jede einzelne ein bisschen Zunder gehalten. Ich habe den Rauch von der Festungsmauer aus beobachtet und eine ganze Weile kein Wort gesagt.", "Die Dragonmaw sind nicht fertig. Sie werden ihre Wunden noch lange in diesen Hügeln lecken, und ich behalte sie im Auge. Aber sie tun es mit Blick auf einen Hafen, der noch steht.", "$gEin vorzüglicher:Eine vorzügliche; $R, so hab ich Euch genannt. Ich würde es vor jedem wiederholen." }, signoff = "Captain Stoutfist\nHafen von Menethil" },
  [36] = { greeting = "$N,", body = { "jeden Morgen gehe ich zum Rathaus, an Mauern vorbei, die die Steinmetzgilde nach dem Krieg errichtet hat. Edwin hat einige dieser Steine selbst gesetzt. Früher habe ich sie Besuchern gezeigt. Damit habe ich aufgehört.", "Ihr habt mir seinen nie abgeschickten Brief gebracht und seiner Spur dann durch das Verlies und darüber hinaus gefolgt. Ich habe gehört, dass Lord Lescovar tot aufgefunden wurde. Ich habe nicht gefragt, wie, und ich werde es nicht tun. Ich bin dankbar. Ich sage es zuerst, weil der Rest schwerer zu sagen ist.", "Als die Adligen sich weigerten, uns zu bezahlen, wurden einigen von uns Posten angeboten. Ich nahm meinen an. Edwin lehnte seinen ab, aus Treue zu den anderen, und schwor Rache. Ich sagte Euch, es sei ihm gleich, wen er verletze, und ich sei nicht sicher, ob ich es ihm verübeln könne. Ich habe meine Meinung zu beidem nicht geändert.", "Die Stadt steht, und ich verwahre ihre Pläne. An manchen Morgen fühlt sich das an wie eine Antwort an ihn, und an manchen wie der Posten, den er nicht annehmen wollte." }, signoff = "Baros Alexston\nStadtarchitekt" },
  [37] = { greeting = "$N,", body = { "ich bin zum Hof zurückgegangen. Zum ersten Mal seit jener Nacht. Die Scheune steht noch, und auch der alte Baumstumpf, unter dem das Buch vergraben war. Ich stand lange dort. Dann kehrte ich in mein Lager zurück und schlief.", "Morbent Fel ist besiegt. Die dunklen Reiter sind es nicht, und ich will nicht so tun, als wäre es anders. Aber ein kleiner Teil dessen, worauf ich wider besseres Wissen gehofft hatte, ist eingetreten, durch Eure Hand und durch jene Klinge aus Sturmwind.", "Ich weiß jetzt, wer Jitters ist. Er sah meine Familie sterben und konnte nichts tun, und er schrieb alles auf, weil er es nicht allein tragen konnte. Ich merke, dass ich einen Mann dafür nicht hassen kann. Ich versuche, es nicht zu tun.", "Vielleicht bringt Euch das Schicksal eines Tages zurück zu mir. Ich meine es so wie damals." }, signoff = "Sven Yorgen" },
  [38] = { greeting = "$N,", body = { "ich habe Alyssa noch einmal die Karten gelegt. Der Tod kam nicht. Es kam eine Karte, die ich lange nicht gesehen hatte, eine schlichte, ganz ohne Bedeutung. Sie steht für einen gewöhnlichen Tag. Ich saß da und sah sie an, bis mein Tee kalt war.", "Ihr seid einem Namen aus meiner Trance gefolgt, zum Register, nach Moonbrook und Goldhain und Sturmwind und wieder zurück, und jede Tür, an die Ihr klopftet, führte zu etwas Älterem und Schlimmerem. Ich habe Euch auf diesen Weg geschickt. Es tut mir leid um manches, was Ihr an seinem Ende gefunden habt.", "Der Wald ist noch immer dunkel. Die Karten sagen es, und was den Dämmerwald angeht, irren sie sich selten. Aber über diesem Haus liegt ein Schatten weniger.", "Alyssa weiß nicht, wie nah es kam, und so soll es bleiben." }, signoff = "Madame Eva" },
  [39] = { greeting = "$N,", body = { "ich schreibe Euch von der Nijelspitze, mit gepackten Taschen für Darnassus. Vahlarriel sagt, ich darf gehen, wenn ich bereit bin. Ich finde immer neue kleine Gründe, noch nicht bereit zu sein.", "Ich habe Euch für den Tod meines Bruders gedankt. Darüber habe ich mehr nachgedacht als über alles, was die Orcs mir angetan haben. Ich meinte es, und ich meinte es nicht, und beides ist noch immer wahr. Wäre es nicht Eure Hand gewesen, dann die eines meiner Leute. Das ist ein kalter Trost, aber es ist der, den ich habe.", "Mein Vater wird fragen, was Tyranis hier draußen wollte. Ich werde ihm die Wahrheit sagen: Wissen, mehr als ihm guttat, mehr als unser Volk erlaubt. Wie es geendet hat, werde ich ihm nicht sagen.", "Ihr habt mich aus dieser Festung geholt und mich auf meinen eigenen Füßen hinausgehen lassen. Daran werde ich mich am besten erinnern." }, signoff = "Dalinda Malem" },
  [40] = { greeting = "$N,", body = { "Quae sagt, ich mache mir zu viele Sorgen. Quae hat recht, und es hat mich nicht ein einziges Mal aufgehalten. Jetzt, wo ich weiß, dass meine beiden Unruhestifter leben, habe ich jemand Neues gefunden, um den ich mir Sorgen machen kann. Euch.", "Ich habe gelesen, was Kin von diesem Hof mitgebracht hat. Nachts, was eine schlechte Angewohnheit ist, denn es ist nicht die Art Lektüre, bei der ein Mann gut schläft. Was auch immer Jorell da draußen zusammenbraut, ich wette meine Stiefel, dass es mit Stanley zu tun hat.", "Mein Vetter will immer noch nicht über diesen Hund reden. Ich kann es ihm nicht verdenken.", "Wie auch immer. Esst etwas Warmes, haltet den Rücken an der Wand und trinkt weniger als Kin." }, signoff = "Phin Odelic\nSouthshore" },
  [41] = { greeting = "$gWerter Kunde:Werte Kundin;,", body = { "bezüglich Eurer jüngsten Anfrage. Der Laib, nach dem Ihr gesucht habt, hat Menethil per Schiff verlassen, lange bevor Ihr anfingt, Fragen zu stellen, wie Ihr ja in Menethil selbst erfahren habt. Unser Freund am Hafen lässt grüßen und sagt, ihm fehle die Aufregung, was ich nicht weitersagen sollte, also tue ich so, als hätte ich es nicht geschrieben.", "Der Rest der Bestellung ist jetzt bei unseren Freunden in Theramore, und das sind vorsichtige Leute. Ob der Laib wieder auftaucht, liegt nicht mehr in meiner Hand.", "Eines sage ich offen. Ihr habt mehr Laufarbeit geleistet, als ich bezahlt habe, und kein Wort davon hat meinen Laden auf anderem Weg erreicht als durch Euch. Das ist mir aufgefallen. Mir fällt das meiste auf." }, signoff = "Mit Dank für Eure Treue\nElling Trias\nKäsemeister" },
  [42] = { greeting = "$N,", body = { "ich habe Caldwell zur verlassenen Wacht geschickt, wie angekündigt. Die Marschen sind nicht so groß und weglos, dass ein Mann sich für immer darin verstecken könnte, auch wenn Reethe entschlossen scheint, es auszuprobieren.", "Jim lächelt noch immer jeden an. Ich bleibe stehen und rede mit ihm, wenn ich kann. Er spricht von dem Gasthaus, als stünde es noch draußen an der Straße, und ich lasse ihn.", "Es ist nie eine gute Nachricht, wenn man mir das Abzeichen eines Wachmanns bringt. Reethes war von der schlimmsten Sorte: ein Mann, der dem alten Admiral so treu war, dass er seinem Eid den Rücken kehrte, und dann zu leichtsinnig selbst für die Deserteure, mit denen er lief. Uns nennen sie die Verräter. Die Ironie gönne ich ihnen.", "Balos Jacken hat Euch gebeten zu vergessen, dass Ihr den Deserteuren je begegnet seid. Bitte tut das nicht." }, signoff = "Captain Garran Mumm\nTheramore" },
  [43] = { greeting = "$N,", body = { "ich bin der Magistrat einer Fischerstadt. Ich schlichte Streit um Netze und Grenzsteine und hin und wieder einen Betrunkenen, der die Tür eines anderen für seine eigene gehalten hat. Für Namen wie die Arguswacht war ich nicht gemacht.", "Dibbs hat jedes Buch, das er besitzt, danach durchsucht und nichts gefunden.", "Ihr habt die Magier im Oberland erledigt, und das Syndikat ist ärmer dafür. Ich wünschte, das wäre das Ende. Aber wem auch immer Nagaz diente, er ist noch irgendwo da draußen, weiter weg als Alterac, und ich bin ein Mann, der gern weiß, wo seine Sorgen wohnen.", "Also blicke ich abends nach Norden, wo ich früher aufs Wasser geblickt habe. Danke, dass Ihr mir gebracht habt, was ich nicht wissen wollte. Besser ich als niemand." }, signoff = "Magistrat Henry Maleb\nSouthshore" },
  [44] = { greeting = "$N,", body = { "die Tafel ist bei den Magiern des Königs, hinter mehr Schlössern, als ich Schlüssel habe. Was sie daraus lernen, sollen sie selbst sagen. Was ich sagen kann, ist, dass sie nie in die Hände der Schattenschmiede gelangt ist und dass sie Hammertoes Traum war, lange bevor sie irgendwen etwas anging.", "Karnik erzählt mir, er habe mit Hammertoes Geist gesprochen. Ich bin Berater, kein Priester, und ich weiß nicht, was ich davon halten soll. Aber er sagt, Hammertoe habe seinen Frieden, und ich habe beschlossen, ihm zu glauben.", "Och. Ein Zwerg, der sein Leben lang gesucht hat, woher unser Volk kommt, und den Rest seiner Tage damit verbracht hat, dafür zu sorgen, dass die falschen Hände es nicht zuerst fanden. Ich hätte es nicht halb so gut gemacht, weder an seiner Stelle noch an Eurer.", "Das ist ein Leben, das den Brief eines Beraters wert ist, und Ihr seid der Grund, warum es nicht vergebens war." }, signoff = "Berater Belgrum\nIronforge" },
  [45] = { greeting = "$N,", body = { "Ihr habt das Gedankenauge aus Mai'Zoths Händen geholt, und das Erste, was ich beschloss, war, nicht hineinzusehen. Wer herausfinden will, ob ein Ding zum Guten gebraucht werden kann, sollte nicht damit beginnen, sich von ihm gebrauchen zu lassen.", "Es ist eingewickelt und weggeschlossen. Ich bete daneben, und ich lese, was andere über solche Dinge geschrieben haben. Wenn Gutes darin steckt, werde ich es finden. Wenn nicht, wird es zerstört, und ich werde ihm nicht nachtrauern.", "Ich denke oft an Colonel Kurzen, wie er war, ein großer und edler Mann. Die Legenden, die Fetische, alles wies auf eine Wahrheit: Was ihn zerbrach, kam von außen. Das ist ein Trost und zugleich eine Warnung. Es hätte jeden von uns treffen können.", "Möge Eure Kraft niemals schwinden, $N." }, signoff = "Bruder Nimetz\nRebellenlager" },
  [46] = { greeting = "$N,", body = { "wie geht's dem Kleinen? Ich hab mich's gefragt, und ein alter Tierbändiger darf sich so was fragen.", "Ein paar Dinge, die man zweimal sagen sollte, wo das Ei doch so früh aufgegangen ist. Grimmlingflitzer fressen Fleisch und Grünzeug, beides, also lasst Euch von keinem was anderes erzählen. Rohe Flanken, wohlgemerkt, und reichlich davon.", "Kinder, was? Eben noch rennt Ihr mit einem Ei um die halbe Welt und habt eine Stunde Vorsprung, und im nächsten Moment seid Ihr $gVater:Mutter;. So halbwegs.", "Haha. Passt auf Euch auf, und auf den Kleinen auch, falls Ihr ihn behalten habt." }, signoff = "Agnar Beastamer\nAerie Peak" },
  [47] = { greeting = "$N,", body = { "Scharfschnabel ist zum ersten Mal mit der ganzen Staffel geflogen. Er war zu weit draußen auf der linken Seite und um die Hälfte zu stolz auf sich, und seine Mutter hat ihn zweimal zurück in die Reihe geholt. Es war das Schönste, was ich seit Jahren von diesem Gipfel aus gesehen habe.", "Ich habe Thadius in Burg Nethergarde Nachricht geschickt, für seinen Anteil daran. Er ist vor langer Zeit dunklerem Wissen nachgegangen, und manche hier wollen seinen Namen noch immer nicht aussprechen. Aber es war sein Blick, der den Kleinen fand, und im Herzen ist er immer noch ein Wildhammer.", "Die Reiter machen ein Lied daraus. Es ist kein gutes Lied. Wildhammerlieder sind es nie, im ersten Jahr. Sie werden es trotzdem singen, lange, lange Zeit, und Euer Name steht in jeder Strophe, die sie bisher haben." }, signoff = "Greifenmeister Talonaxe\nAerie Peak" },
  [48] = { greeting = "$N,", body = { "hier schreibt Emma Felstone. Ich habe mir angewöhnt, wieder so zu unterschreiben, nach all den Jahren. Es fühlt sich an wie ein Mantel, den ich bei jemandem vergessen hatte.", "Ich habe alles durchgesehen, was Janice geschickt hat. Alte Briefe. Ein Rezept von Mutter, das ich vergessen hatte. Die Urkunde für den Hof, ausgerechnet, als ob ich je dorthin zurückginge. Sie hat immer gepackt, als zöge sie für immer ein.", "Ich habe Euch einen Grabräuber genannt. Ich sage einmal, schlicht, dass es mir leidtut, und dann reden wir nicht mehr davon. Es tut mir leid.", "Wenn dieses Amulett getan hat, was ich hoffte, dann ruht sie jetzt und wartet nicht mehr auf eine Lieferung. Wenn nicht, sagt es mir nicht. Ich glaube lieber, dass es gewirkt hat." }, signoff = "Emma Felstone" },
  [49] = { greeting = "$N,", body = { "ich verstehe nicht, warum der Kriegshäuptling ein so kleines Ding will. Ein kleines Kettchen, ein kleiner Stein. Ich habe Krieger für weniger sterben sehen und für mehr, und ich weiß nicht, was davon das hier ist. Ich habe es trotzdem nach Orgrimmar geschickt, in das Gepäck eines Reiters eingenäht. Ich folge ihm. Das hat mir bisher genügt, und es genügt mir jetzt.", "Gol'dir hat Euch gesagt, er werde seinen eigenen Weg gehen, sobald seine Angelegenheiten erledigt sind, und ich glaube ihm. Er ist ein Orc, der zu seinem Wort steht.", "Was das Mädchen angeht, hoffe ich, dass sie irgendwohin gegangen ist, weit weg von diesem Anwesen. Sie wurde dort gegen ihren Willen festgehalten, wie unsere Krieger in Durnholde festgehalten wurden. Ich bin froh, dass ihr niemand etwas getan hat." }, signoff = "Krusk\nTarrens Mühle" },
  [50] = { greeting = "$N,", body = { "wieder stand ein Jungspund auf den Planken über der Schlucht und konnte den Sprung nicht wagen. Ich habe nicht gestoßen. Glaube, den man stößt, ist kein Glaube.", "Ich habe ihm gesagt, was ich Euch gesagt habe: der Geist, der Körper, der Verstand. Ihr wurdet in allen dreien geprüft, und keiner von uns hat es Euch leicht gemacht. Parqual hielt das alles für Schwindel. Braug dachte, Ihr könntet vergessen, was Ihr gelesen habt. Ich habe immer nur gedacht, dass Ihr springen würdet.", "Ihr kamt zu mir nach Hause, und Ihr kamt verwandelt zurück. Ihr kamt im Gleichgewicht zurück, und das ist seltener als Stärke.", "Bewahrt das Gleichgewicht." }, signoff = "Dorn" },
  [51] = { greeting = "$N,", body = { "dass sich ein ungeschickter Oger mit nichts als einer Krone so lange dem Willen der dunklen Fürstin entziehen konnte, beunruhigt mich mehr, als wenn die Krone aus Gold gewesen wäre. Große Macht sollte wenigstens den Anstand haben, auch danach auszusehen.", "Die Krone ist überbracht. Ich habe sie der dunklen Fürstin selbst gebracht, und ich gestehe, ich hielt sie ein wenig von mir weg, wie man etwas trägt, das beißen könnte.", "Sie hat von Eurem Anteil daran gehört. Dafür habe ich gesorgt, wie ich es versprochen hatte. Euer Name wurde am Hof von Undercity ausgesprochen, und das können die wenigsten Lebenden von sich sagen." }, signoff = "Sharlindra" },
  [52] = { greeting = "$N,", body = { "Ihr werdet die Länge dieses Schreibens verzeihen. Bei meinem Volk gilt ein langer Satz entweder als Zeichen von Genie oder als Symptom einer Krankheit, und ich habe beschlossen, für ein Genie gehalten zu werden.", "Mok'Morokk floh wie ein ängstliches Kind, und obgleich er seither zurückgekrochen ist, um unter uns zu schmollen, hat es in Brackenwall niemand vergessen. Der Klan berät nun über seinen Nachfolger. Oger beraten nach Art eines Steinschlags: langsam, lautstark und mit Verletzten. Tharg gäbe einen vortrefflichen Anführer ab, wäre er jünger und weniger gebrochen.", "Derweil verweilt Onyxias Brut im Süden, und ich verweile als Einziger in Brackenwall, den das Warum bekümmert. Eure Mühen unter den Eiern haben uns Zeit erkauft. Ich gedenke, sie weise zu verwenden, was mich in diesem Dorf zu einer Art Sonderling macht." }, signoff = "Mit vorzüglicher Hochachtung\nDraz'Zilb" },
  [53] = { greeting = "$N,", body = { "die Gelehrten haben den Anhänger, und sie sind langsam, wie es sich für Gelehrte gehört. Ich habe ihn mir selbst oft angesehen. Menschen legen mehr von sich in ein Schmuckstück als ein Orc in ein Schwert.", "Worauf ich immer wieder zurückkomme, ist der Spion, der ihn genommen hat. Er beobachtete Theramore wochenlang, allein, nahm den Anhänger in seiner letzten Nacht, und auf dem Heimweg tötete ihn ein Krebswesen. Er hat seine Mission nicht vollendet. Ihr habt sie für ihn vollendet. Wenn Geister für so etwas Ruhe finden, sollte seiner sie finden.", "Ein Scharfseher lernt zu warten, und ich werde auf den Anhänger warten, so lange er es verlangt. Unser Spion hatte diesen Luxus nicht. Ich bin froh, dass er Euch hatte." }, signoff = "Zor Lonetree" },
  [54] = { greeting = "$N,", body = { "die Arglist des Raptors hat nachgelassen, wie ich es wusste. Dann haben Gor'mul und ich gesprochen, so wie ich es gehofft hatte.", "Er hörte zu. Er lächelte nicht, und ich bat ihn nicht darum. Er fragte, ob der junge Kriegshäuptling wirklich Orgrims Rüstung trägt und seinen Hammer führt, und ich sagte ja. Danach schwieg er lange. Dann fragte er, was die Schamanen jetzt vermögen, und ich zeigte ihm ein wenig, und er warf es nicht zu Boden.", "Das ist kein heimgekehrter Krieger. Aber es ist ein Krieger, der eine Frage gestellt hat, und in all den Jahren, die er allein umherzog, hat er, glaube ich, niemanden etwas gefragt.", "Ihr habt ihn einen Teil des Weges zurückgebracht, $N, und der Rest des Weges gehört ihm." }, signoff = "Tor'gan\nHammerfall" },
  [55] = { greeting = "$N,", body = { "Trol'kalar ist auf dem Weg zu Nimboya in Grom'gol, in drei Tücher gewickelt und von zwei unserer Schnellsten getragen, weil keiner dem anderen das Tragen allein überlassen wollte.", "Ihr wisst, was der Name bedeutet, mon. Trolltöter. Generation um Generation trugen es die Männer von Strom und Arathor gegen mein Volk, und die Großväter unserer Großväter lernten, bei seinem Anblick zu fliehen. Jetzt hat ein Troll es gehalten. Ich habe es gehalten. Meine Hände zitterten, und ich schäme mich nicht, es zu sagen.", "Man wird es dort brauchen, wo unser Volk kämpft, in den dampfenden Wäldern von Zul'Gurub. Ob es sich erinnert, für welche Seite es geschmiedet wurde, kann ich nicht sagen.", "Dass es überhaupt in unseren Händen ist, ist Euer Werk, $N." }, signoff = "Zengu\nHammerfall" },
  [56] = { greeting = "$N,", body = { "der Häuptling schickte mich über das Meer, um seinen jüngsten Sohn zu finden, und ich werde ihn selbst nach Hause tragen. Nicht so, wie er ging. In einem Edelstein, nicht größer als meine Faust, er selbst, endlich frei von Zanzil. Das ist mehr, als ich zu hoffen wagte, als ich am Kessel die Köpfe der Bloodscalp zählte.", "Die Große Schlange hat ihn vor der Axt der Kopfjäger bewahrt, und Ihr habt ihn vor dem Rest bewahrt. Eine Seele, die so lange ein anderer festhielt, erwacht nicht auf einmal. Die Darkspear kennen Geduld. Wir haben einst ein ganzes Meer überquert und sind für ihn zurückgekommen.", "Unser Stamm wird Euren Namen in Liedern ehren, mon. Das Ritzen in Stein überlasse ich den Schnitzern." }, signoff = "Nimboya\nDas Basislager von Grom'gol" },
  [57] = { greeting = "$C,", body = { "die Fetische sind Asche. Ich habe sie selbst am Rand des Tränenteichs verbrannt, mit dem Wind im Rücken. Was immer in ihnen war, hat lange gebraucht, bis es aufhörte zu rauchen.", "Ich denke immer wieder an diesen Verbannten im Hinterland. Er sah sich die Prophezeiung seines Hohepriesters an und sagte, was er sah, und sie schrieben sein Urteil mit Blut auf getrocknetes Fleisch und schickten ihn zu den Witherbark. Jede Armee, in der ich gedient habe, hatte einen Mann wie ihn. Die meisten hatten recht.", "Jammal'an glaubt noch immer, sein Gott werde den Atal'ai Unsterblichkeit gewähren, und die grünen Drachen beobachten das Wasser und warten auf den Tag, an dem er es versucht." }, signoff = "Fel'zerul\nStonard" },
  [58] = { greeting = "$N,", body = { "das Lager hält, und die Waldpfoten greifen es seltener an, wie meine Wachen sagen. Jahrelang hielt ich sie für einfache Wilde. Eure Karte hat mich eines Besseren belehrt. Sie kämpften an zwei Fronten, und die im Süden war es, die sie zermürbte. Etwas trieb sie nach Norden, und wir standen im Weg.", "Ich habe die Drüsen, die Ihr Zornstachel herausgeschnitten habt, studiert, bis ich sie aus dem Gedächtnis zeichnen konnte. Was immer in der Gewundenen Tiefe lebt, ist organisiert und geduldig und näher, als mir lieb ist. Es ist meine Aufgabe, dafür zu sorgen, dass wir lange genug standhalten, um daraus zu lernen.", "Zum ersten Mal in meinem Leben habe ich Mitleid mit Gnollen, und ich hätte sie lieber weiter gehasst." }, signoff = "Hadoken Swiftstrider\nCamp Mojache" },
  [59] = { greeting = "$N!", body = { "Hah! Das Gefäß ist bereit, mon, und die Materialien, die Ihr gebracht habt, sind besser, als ich verlangt habe. Abgesplittertes Treantholz, Mineralien von den Riesen, Sehnen von Eulenbestien, all die kleinen Metallfragmente. Ich habe jedes Stück selbst sortiert, nach Geruch.", "Neeru sagt, er war mit dem Kopf zufrieden. Ein guter Kunde, der. Er stellt keine Fragen, und er bezahlt in Kräutern.", "Was der Muisek und das Gefäß zusammen ergeben, ist meine Sache und die der Geister. Aber so viel sage ich Euch. Als ich das letzte Fragment hineinlegte, wurde die ganze Hütte still, so wie ein Dschungel still wird, wenn etwas Großes lauscht.", "Ihr habt gute Hände zum Sammeln, $N, und ein Hexendoktor achtet immer auf Hände." }, signoff = "Hexendoktor Uzer'i\nCamp Mojache" },
  [60] = { greeting = "$N,", body = { "Ihr habt hart gearbeitet in diesem Schnee. Vier Arten von Wildekin, jede schlimmer als die vorige, und Ihr habt Euch durch alle hindurchgekämpft.", "Ich habe Winterspring immer nur vom Ausgang der Tunnel der Holzschlundfeste aus gesehen, weiß und still. Ihr habt mehr davon gesehen als ich. Wenn sich unsere Wege kreuzen, würde ich gern hören, wie diese Höhlen im Süden aussahen.", "Was für ein Geheimnis treibt seine eigenen Wächter in den Wahnsinn? Darüber grüble ich jeden Abend, seit die Läufer zurückkamen. Was die Nachtelfen dort draußen zurückgelassen haben, wurde nicht für uns zurückgelassen, und genau deshalb müssen wir es kennen." }, signoff = "Trull Failbane\nBlutgiftposten" },
  [61] = { greeting = "$N,", body = { "darf ich es noch einmal sagen? Ein Triumph! Ich habe es jedem im Bollwerk gesagt, der lange genug stillstand.", "Ich liebe einen Plan, der aufgeht, und unserer ging dreimal auf. Wie ich höre, hat der Kreuzzug unser Banner gefunden und sich geradewegs auf die Geißel gestürzt, genau wie erhofft. Die Türme leuchteten auf den Suchgeräten meiner Priester auf wie Leuchtfeuer auf einer Karte. Und dann seid Ihr nach Andorhal hineinmarschiert und habt mir einen Splitter von Arajs Phylakterium gebracht, und das ist der eine Teil, den sich kein Plan von mir zugutehalten kann.", "Die Geißel wird Andorhal nicht wegen eines gefallenen Lichs aufgeben, und ich will Euch nicht beleidigen, indem ich etwas anderes behaupte. Aber sie wird sich erinnern, wer den Kreuzzug auf sie gehetzt hat, wer ihre Türme markiert hat und wer danach hineinging." }, signoff = "Hochexekutor Derrington\nDas Bollwerk" },
  [62] = { greeting = "$N,", body = { "ich bin immer noch Payson. Das will ich vor allem anderen klargestellt haben. Ich habe den Namen angenommen, nachdem ich in dieses glorreiche Unleben erwacht bin, und ein Paket von einer Toten ändert daran nichts.", "Ich habe Euch einen echten Aasgeier genannt. Ihr wart es nicht, wie sich herausstellte, und ich merke, dass es mich weniger stört, mich geirrt zu haben, als ich dachte.", "Aber ich habe behalten, was sie geschickt hat. Alles. Es liegt in einer Kiste unter den Kakerlakenkisten, wo niemand nachsehen wird, und darum geht es ja gerade." }, signoff = "Jeremiah Payson\nKakerlakenverkäufer" },
  [63] = { greeting = "$N,", body = { "noch immer der achtzehnte Fahrer! Ich weiß. Ich bin genauso überrascht wie Ihr.", "Der Booster ging genau so los, wie Shreev es gesagt hatte, will sagen: auf einmal. Streckenrekord? Zertrümmert. Außerdem zwei Kisten und der Großteil meiner Augenbrauen. Die Augenbrauen wachsen nach.", "Ich wollte sehen, wie die Gnome mir zusehen. Hat nicht geklappt. Zu schnell. Das ist das Problem, wenn man bis zum Anschlag geht: Man verpasst die Landschaft.", "Pozzik schraubt schon am neuen Regler herum und murmelt was von Sicherheit.", "Danke für die ganze Lauferei, $N. Ich war damit beschäftigt, schnell zu sein." }, signoff = "Razzeric\nDie Schimmernde Ebene" },
  [64] = { greeting = "$N,", body = { "eine kurze Notiz, da ich mitten in etwas bin. Ich bin immer mitten in etwas.", "Die Armschienen der Steinbindung waren von unschätzbarem Wert. Zwei davon jedenfalls. Servo hat die anderen drei verlegt, und genau deshalb hatte ich Euch um fünf gebeten, was die Methode recht eindrucksvoll bestätigt.", "Die Fesseln machen Fortschritte. Wenn sie fertig sind, wird ein Magier Elementare von einer Stärke binden können, wie sie noch niemand gebunden hat, vorausgesetzt, der Koeffizient benimmt sich, was er tun wird, jetzt, da ich den Sand berücksichtigt habe.", "Lucien erzählt mir, er habe Euch aus den übrigen Steinen etwas angefertigt. Das hätte ich natürlich selbst getan, wäre ich darauf gekommen, was aber nicht geschah, weil ich an die Fesseln dachte." }, signoff = "Dankbar und in Eile\nLotwil Veriatus" },
  [65] = { greeting = "$N,", body = { "die Erde hat Euren Namen jetzt im Mund. Es ist ein guter Name.", "Ihr habt Khan Hratha gefällt. Ihr habt Khan Jehn gefällt. Die Magram sind schon schwach. Ich höre ihre Bäuche noch knurren, wenn der Wind richtig steht. Ich lache jedes Mal.", "Der rote Kristall liegt nachts warm in meinen Händen. Meine Magie ist jetzt stark, stärker, als irgendein Khan glaubte. Sie vertrauten auf ihre Kraft. Sie hörten nicht auf die Erde. Die Erde erinnert sich, wer nicht zugehört hat.", "Euer Name wird an unseren Feuern schon genannt. Die Erde kennt ihn, und ich werde lauschen." }, signoff = "Uthek die Weise" },
  [66] = { greeting = "$N,", body = { "unter Freunden also.", "Die letzte Ladung ist hinaus auf die Ebene gegangen, und man sagt mir, die Boxencrews seien danach ein, zwei Tage sehr still gewesen. Derweil scheinen in Booty Bay recht viele Leute mir einen Drink zu schulden, und ich habe aufgehört, meine eigenen zu bezahlen.", "Zanzils Mixtur macht seltsame Dinge mit Hefe. Mit Leuten auch, aber Hefe ist mein Geschäft, und an Eurer Stelle würde ich es dabei belassen.", "Wisst Ihr, was ich an Euch mag? Ihr habt einen finsteren Plan von Booty Bay zur Ebene und zurück getragen und nicht ein einziges Mal gefragt, wofür er gut ist. Ich habe Euch damals ein wenig extra dafür bezahlt. Dieser Brief ist keine Bezahlung. Betrachtet ihn als Kompliment, von einem Mann, der keine verschenkt." }, signoff = "Crank Fizzlebub\nBooty Bay" },
  [67] = { greeting = "$N,", body = { "Millionen! Na ja. Tausende, beinahe. Na ja, eine sehr ermutigende Zahl von Hunderten, und es werden mehr!", "Das fabelhafte Noggenfogger-Elixier verkauft sich besser als alles in Gadgetzan, was kein Wasser ist. Die Kunden kommen wieder, und das ist das Zeichen eines Qualitätsprodukts. Manche kommen ein bisschen kleiner wieder, oder ein bisschen knochiger, oder sie schweben von irgendwo herab, aber sie kommen wieder, und darauf kommt es an.", "Sprinkle erzählt allen, ich schulde ihr einen Gefallen. Komische Frau. Das Pulver war ihre Idee, schon, aber das Geniale lag im Umrühren.", "Ihr wart von Anfang an dabei, $N, als es noch nach dem Inneren einer Taudrüse schmeckte, und daran werde ich mich erinnern, wenn ich berühmt bin." }, signoff = "Marin Noggenfogger\nGadgetzan" },
  [68] = { greeting = "$N,", body = { "es kommt in Stücken zurück. Ein Geruch nach Salz. Ein weites Feld, neben dem ich, glaube ich, aufgewachsen bin. Ein Lied, das jemand summte, während er Klingen schärfte. Nichts davon in der richtigen Reihenfolge und nichts davon besonders nützlich, aber alles meins.", "Die Goldene Flamme kommt in meine Heimat, wo sie beschützt werden kann. Ich erinnere mich jetzt an den Weg. Das ist neu.", "Ich habe Euch einmal einen Rat gegeben: Es ist gefährlich, allein zu gehen. Ich hätte gut daran getan, ihn selbst zu befolgen.", "Ohne Euch würde ich noch immer durch diesen Krater irren und Fremde nach meinem eigenen Namen fragen." }, signoff = "Linken\nMarshals Zuflucht" },
  [69] = { greeting = "$N,", body = { "ich habe Euch beobachtet, wisst Ihr. Als das letzte Räuchergefäß in der Schattenfeste erlosch, konnten meine Zauber wieder sehen, und das Erste, was sie mir zeigten, wart Ihr, wie Ihr im Rauch standet. Ich habe in meinem Leben sehr vieles erspäht. Ich glaube nicht, dass ich mich je so gefreut habe, etwas zu sehen.", "Islen schickte mit dem Wasser ihre Grüße und eine Warnung, die ich seither immer wieder hin und her wende: dass das, womit ich es aufnehme, größer ist, als ich weiß, und dass ich es bald genug erfahren werde. Sie irrt sich selten. Der Schattenrat wurde in Jaedenar am Kopf getroffen, aber eine Schlange wie diese hat mehr als einen.", "Der Teufelswald ist noch immer krank, und er wird es noch lange sein. Aber in einem dunklen Winkel ist er ein wenig weniger krank, und die Erdenmutter sieht das, auch wo es sonst niemand sieht." }, signoff = "Möge die Erdenmutter Euch behüten,\nGreta Mosshoof\nDas Smaragdrefugium" },
  [70] = { greeting = "$N,", body = { "solange ich sie kenne, waren meine Freunde die Klugen. Legacki, Sprinkle und ihre Kochkunst, Quixxil und was auch immer Quixxil tut. Meine Ideen waren die, über die man lachte, also behielt ich sie in der Tasche.", "Damit ist Schluss! Der Yeti ist wieder zu Hause, an einem Ohr ein bisschen angesengt, und jedes Mal, wenn ich ihn ansehe, denke ich: Den habe ich gemacht. Einen ganzen Yeti. Nach einer Zeichnung.", "Sie haben übrigens alle zurückgeschrieben. Ich verrate Euch nicht, was sie geschrieben haben, Ihr wart ja bei fast allem dabei. Aber zwei von ihnen haben gefragt, wie er funktioniert, und das ist die Stelle, die ich immer wieder lese.", "Ihr habt für mich einen mechanischen Yeti um die halbe Welt getragen, $N. Noch nie hat jemand für mich etwas so Albernes getan. Danke." }, signoff = "Umi Rumplesnicker\nEverlook" },
  [71] = { greeting = "$N,", body = { "ich schlafe nicht gut, seit Ihr mir dieses Buch gebracht habt. Die Annalen von Darrowshire. Meine Heimat, aufgeschrieben von jemandem, der nicht dort war, und dann weitergeschrieben von etwas, das ich nicht verstehe.", "Darin steht, dass mein Bruder Joseph sich gewandelt hat. Dass er verdorben wurde und die Verteidiger verriet und dass sie dafür starben. Ich war einer der Verteidiger. Ich habe überlebt. Bis ich es las, wusste ich nicht, wer uns verraten hatte.", "Der Schädel und das zerbrochene Schwert sind weggeschlossen. Mir gefällt nicht, was ich fühle, wenn ich sie berühre, also berühre ich sie nicht.", "Joseph hatte eine Tochter. Ich habe mir seit Jahren nicht erlaubt, an sie zu denken." }, signoff = "Carlin Redpath\nKapelle des Hoffnungsvollen Lichts" },
  [72] = { greeting = "$N,", body = { "mein Sohn hat Euch von seinem Traum erzählt, in dem ich endlich an seiner Seite im Orden stand. Er wollte, dass er endet.", "Jetzt träume ich. Denselben Traum, glaube ich. Ich stehe an seiner Seite. Er ist ein Junge mit einem Spielzeughammer, und dann ist er ein Mann in seiner Rüstung, und dann ist er fort. Ich erwache vor dem Ende. So viel Gnade gewährt das Licht.", "Der Orden ist wiedergeboren. Ich wollte ihn nicht auf diese Weise aufnehmen. Aber Taelan hatte sein Banner einst niedergeworfen, und Ihr habt es ihm zurückgebracht, und ich werde es nicht ein zweites Mal fallen lassen." }, signoff = "Tirion Fordring" },
  [73] = { greeting = "$N,", body = { "man sagt mir, Eure Art schreibe, wenn sie dankbar ist. Zeichen auf einer dünnen Haut, gefaltet und von Hand zu Hand getragen. Es ist ein langsamer Weg, zu sagen, was eine Flut auf einmal sagt. Aber Ihr habt uns die Hände von vier Hauptmännern des Feuers gebracht, und so will ich es auf Eure Weise versuchen.", "Ich verstehe nicht, wie Eure Art Dankbarkeit bemisst. Ich beobachte die Sterblichen seit Langem, und ich habe gesehen, wie sie einander für sehr kleine Dinge danken: eine aufgehaltene Tür, einen gefüllten Becher. Was Ihr getan habt, war kein kleines Ding. Ich weiß nicht, wie groß ein Brief bei Euch sein muss für etwas so Großes.", "Dieser hier muss genügen. Der Krieg geht weiter. Aber die Kunde von Euch ist durch die Kammern der Wasserlords gegangen." }, signoff = "Fürst Hydraxis" },
}
-- (the places Classic Era's client names otherwise, swapped in there)
ns.classicNames = { ["Sturmwind"] = "Stormwind", ["der Gewundenen Tiefe"] = "der verwundenen Tiefe", ["Die Schimmernde Ebene"] = "Die schimmernde Ebene", ["Kapelle des Hoffnungsvollen Lichts"] = "Kapelle des hoffnungsvollen Lichts" }
